CREATE TEMPORARY PROCEDURE SNOWPARK_TOTAL() RETURNS VARCHAR LANGUAGE PYTHON RUNTIME_VERSION='3.12' PACKAGES=('snowflake-snowpark-python') HANDLER='main' EXECUTE AS CALLER AS $$
from snowflake.snowpark.functions import sum as sf_sum
def main(session):
    result = session.table('SRC').agg(sf_sum('AMOUNT').alias('TOTAL')).collect()
    return str(result[0]['TOTAL'])
$$
